            // Stage ID  
            stage_id <= stage_if;  
            reg_id <= reg_if;  

            // Stage EX  
            stage_ex <= stage_id;  
            reg_ex <= reg_id;  

            // Stage MEM  
            stage_mem <= stage_ex;  
            reg_mem <= reg_ex;  

            // Stage WB  
            stage_wb <= stage_mem;  
            reg_wb <= reg_mem;  

            // Outputs  
            opcode_out <= stage_wb;  
            reg_out <= reg_wb;  
        end  
    end  
endmodule

