description:
Implement a simple version of the ChaCha20 stream cipher's quarter-round function. The quarter-round function takes four 32-bit input words and produces four 32-bit output words. The function is defined as follows:
1. a += b; d ^= a; d = rotate(d, 16);
2. c += d; b ^= c; b = rotate(b, 12);
3. a += b; d ^= a; d = rotate(d, 8);
4. c += d; b ^= c; b = rotate(b, 7);
The module should have a clock input, a reset input, and four 32-bit input words, producing four 32-bit output words. The outputs should be valid after a clock cycle following the input. The reset should initialize the outputs to zeros.

code:
module quarter_round (
    input clk,
    input rst,
    input [31:0] a_in,
    input [31:0] b_in,
    input [31:0] c_in,
    input [31:0] d_in,
    output reg [31:0] a_out,
    output reg [31:0] b_out,
    output reg [31:0] c_out,
    output reg [31:0] d_out
);
    reg [31:0] a, b, c, d;

    function [31:0] rotate;
        input [31:0] value;
        input [5:0] shift;
        begin
            rotate = (value << shift) | (value >> (32 - shift));
        end
    endfunction

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_out <= 32'b0;
            b_out <= 32'b0;
            c_out <= 32'b0;
            d_out <= 32'b0;
        end else begin
            a = a_in;
            b = b_in;
            c = c_in;
            d = d_in;

            a = a + b;
            d = d ^ a;
            d = rotate(d, 16);
            c = c + d;
            b = b ^ c;
            b = rotate(b, 12);
            a = a + b;
            d = d ^ a;
            d = rotate(d, 8);
            c = c + d;
            b = b ^ c;
            b = rotate(b, 7);

            a_out <= a;
            b_out <= b;
            c_out <= c;
            d_out <= d;
        end
    end
endmodule

